-- Rifts World Book 34: Northern Gun Two - its bestiary and its notable NPCs.
-- 0 creatures (migration 074) and 4 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~335-northern-gun-2-npcs-a.sql
--
-- Written by scripts/bestiary-sql.mjs from 1 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.

INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('ng-gerhardt-fulcon', 'Gerhardt "the Falcon" Fulcon', 'Gerhardt Friedrich', 'Robodome Lightweight Champion (Triax Ulti-Max)', 'rifts', 'Human', '6th level Power Armor Commando (NGR) (as printed)', 6, 'Unprincipled', '33', '5 feet, 10 inches (1.78 m)', '188 lbs (85 kg)', '{"IQ":17,"ME":12,"MA":11,"PS":14,"PP":23,"PE":15,"PB":19,"Spd":13}', 46, 32, NULL, NULL, NULL, NULL, NULL, '{"attacks":6}', 'Hand to hand: expert, six attacks per melee when outside a robot. The block prints no combat bonuses, saving throws or Horror Factor, and none are derived here.', '[{"name":"Climbing","pct":75},{"name":"Computer Operation","pct":75},{"name":"Demolitions","pct":95},{"name":"Demolitions Disposal","pct":95},{"name":"Electronic Countermeasures","pct":65},{"name":"Intelligence","pct":62},{"name":"Language: American","pct":75},{"name":"Language: Euro","pct":98},{"name":"Literacy: Euro","pct":95},{"name":"Mathematics: Basic","pct":90},{"name":"Hover Craft (ground)","pct":85},{"name":"Jet Packs","pct":72},{"name":"Robots & Power Armor","pct":91},{"name":"Radio: Basic","pct":90}]', 'Skills of note only; the block prints no full list. Climbing is printed 75%/65% (the second figure is rappelling). Piloting and math skills carry their catalog names (printed as Pilot: Hovercraft, Pilot: Jet Pack, Pilot: Robots & Power Armor and Math: Basic); Language: American has no catalog row and keeps its printed name. Without percentages: Boxing, Robot Combat Elite: Jaeger, Robot Combat Elite: X-10A Predator, Robot Combat Elite: T-31 Super Trooper, Robot Combat Elite: Ulti-Max, Running, W.P. Energy Rifle, W.P. Heavy M.D. Weapons and Hand to Hand: Expert.', NULL, 'None.', 'None.', NULL, 'Built-in clock calendar and an internal computer.', 'Prefers Triax and NGR hardware; his sidearm is a Triax pump pistol (the TX-5 Triax Pump Pistol). Body armor: Plastic-Man - Full Environmental Body Armor. Machines: a souped-up X-1000 Ulti-Max Power Armor (his ring suit, with its Triax force field), the Mantis Power Armor and a T-C20 Terrain Hopper Power Armor (printed TC-20). Vehicles: a Manistique Imperium hovercar with extra armor (120 M.D.C.); he also likes fast hovercycles and rocket bikes.', NULL, 'Serious and focused, with a soldier''s reserve. He is civil enough, but spends little on luxuries, skips most parties unless a sponsor needs him there, and keeps even the gladiators he respects at arm''s length as rivals. Many in the league take that distance for snobbery and find him dull; in truth he simply lives for the work, which leaves him forever the outsider.', 'Maximilian Schroeder, a fellow emigre from the New German Republic and a former Heavyweight Champion, who has taken him on as a protege (from the text; the block prints no allies line).', NULL, 'Reigning Lightweight Champion of the Robodome, an Austrian mercenary who crossed to North America and stayed. He fights in a classic Triax Ulti-Max with its force field, and is a fine pilot and a fierce competitor, if no showman. He is said to be offering twice the Black Market price to whoever can bring him the newer Triax successor to the Ulti-Max. Dark eyes and features, short blond hair in a military cut, and a soldier''s bearing. Also known as Gerry Falcon and Gerry Falco.', 'Rifts World Book 34: Northern Gun Two p.23'),
('ng-brandon-church', 'Brandon "Kid Silver" Church', 'Brandon Church', 'Robodome Middleweight Champion (USA Glitter Boy)', 'rifts', 'Human', '6th level Glitter Boy Pilot (as printed)', 6, 'Unprincipled (started out Scrupulous)', '28', '6 feet, 2 inches (1.88 m)', '193 lbs (87 kg)', '{"IQ":13,"ME":19,"MA":15,"PS":18,"PP":26,"PE":19,"PB":21,"Spd":19}', 41, 24, NULL, NULL, NULL, NULL, NULL, '{"attacks":5}', 'Hand to hand: expert, five attacks per melee when outside a robot. The block prints no combat bonuses, saving throws or Horror Factor, and none are derived here.', '[{"name":"Basic Electronics","pct":65},{"name":"Basic Mechanics","pct":80},{"name":"General Repair & Maintenance","pct":70},{"name":"Land Navigation","pct":62},{"name":"Language: American","pct":95},{"name":"Language: Euro","pct":85},{"name":"Language: French","pct":85},{"name":"Robots & Power Armor","pct":71},{"name":"Hovercycles, Skycycles & Rocket Bikes","pct":85},{"name":"Radio: Basic","pct":80},{"name":"Sensory Equipment","pct":65},{"name":"Weapon Systems","pct":75}]', 'Skills of note only; the block prints no full list. The piloting skills carry their catalog names (printed as Pilot: Robots & Power Armor and Pilot: Hovercycles); Language: American and Language: French have no catalog rows and keep their printed names. Without percentages: Robot Combat Elite: Glitter Boy, W.P. Energy Pistol, W.P. Energy Rifle, W.P. Heavy M.D. Weapons and Hand to Hand: Expert.', NULL, 'None.', 'None.', NULL, 'None.', 'Leans toward Wilk''s weapons and carries a Wilk''s 320 Laser Pistol when he expects trouble or leaves Northern Gun. Body armor: Urban Warrior - Padded Environmental Body Armor, and hovercycle ride armor (printed as Hovercycle Ride Armors; no model named). Machines: a modified Glitter Boy Power Armor (USA-G10) whose Boom Gun is replaced by a disguised Naruni (NE) plasma cartridge machine-gun, with a retractable Vibro-Short Sword in the left forearm; also the Midas Power Armor and the Ironwing Flying Power Armor (printed NG-X16 Midas and NG-23F Ironwing). Vehicles: hovercycles, jeeps and ATVs.', NULL, 'Once dreamed of becoming a Cyber-Knight, but years of fame and comfort have softened the hero for hire into a party-loving champion who never wants to go back to the hardscrabble life he was born to. Friendly and never cutting, though success has made him cocky and showy.', NULL, 'Anyone who learns his gun is Naruni: he lives in fear of being caught with Naruni plasma cartridges (from the text; the block prints no enemies line).', 'Grew up on the Iron Fields at Ishpeming''s western edge and spent his youth exploring the Wisconsin Wildland for pre-Rifts ruins. After vanishing for almost two months on one trip, he came home wearing a near-pristine Glitter Boy he claims to have dug out of a ruin. He worked as a knight-errant for some years, then joined the Robodome, where the suit made him a rising star and now the Middleweight Champion; he sometimes fights Heavyweight bouts to please the crowd. His secret: the Boom Gun hangs over his mantle, and the ring weapon in its place is a Naruni plasma cartridge machine-gun rebuilt to pass for an Earth-made plasma ejector. He would swap it if he could find anything as compact and powerful. Tough and athletic, with shaggy russet hair and fair skin.', 'Rifts World Book 34: Northern Gun Two p.23-24'),
('ng-shelaine-truman', 'Shelaine "Huntress" Truman', 'Shelaine Truman', 'Robodome Robo-Gladiator, Heavyweight contender', 'rifts', 'Human', '6th level Robo-Gladiator (as printed)', 6, 'Unprincipled', '24', '5 feet, 3 inches (1.6 m)', '108 lbs (49 kg)', '{"IQ":20,"ME":19,"MA":15,"PS":11,"PP":28,"PE":15,"PB":19,"Spd":16}', 32, 20, NULL, NULL, NULL, NULL, NULL, '{"attacks":5}', 'Hand to hand: martial arts, five attacks per melee when outside her robot. The block prints no combat bonuses, saving throws or Horror Factor, and none are derived here.', '[{"name":"Basic Mechanics","pct":60},{"name":"Computer Operation","pct":75},{"name":"Navigation","pct":80},{"name":"Performance","pct":60},{"name":"Robots & Power Armor","pct":95},{"name":"Public Speaking","pct":55},{"name":"Radio: Basic","pct":80},{"name":"Robot Mechanics","pct":45},{"name":"Sensory Equipment","pct":70},{"name":"Weapons Engineer","pct":65},{"name":"Wardrobe & Grooming","pct":77},{"name":"Weapon Systems","pct":80}]', 'Skills of note only; the block prints no full list. Robots & Power Armor carries its catalog name (printed as Pilot: Robots & Power Armor). Without percentages: Robot Combat: Basic, Robot Combat Elite: Beachmaster, Robot Combat Elite: Hunter Mobile Gun, Robot Combat Elite: Samson Power Armor, W.P. Heavy M.D. Weapons and Hand to Hand: Martial Arts.', NULL, 'None.', 'None.', NULL, 'None.', 'Favorite personal weapons: the NG-33 Northern Gun Laser Pistol and the L-20 Pulse Rifle. Body armor: Plastic-Man - Full Environmental Body Armor, and the NG RA5 Arrow Ride Armor (printed as the Arrow Hovercycle Ride Armor). Machines: the Hunter Mobile Gun NG-V7, the Beachmaster Amphibious Combat Robot (printed NG-V36 Beachmaster) and the NG-X9 Samson Power Armor; the block does not say which Hunter variant. Vehicles: hovercycles, rocket bikes and jet packs.', NULL, 'Feels she must keep proving herself as the youngest regular, and a woman, in the league, and uses wit and fast reflexes to punish anyone who underestimates her. Driven in the ring but fun outside it: she loves the fame and the parties, roughhouses and jokes like one of the guys, and the male gladiators treat her as a kid sister, quick to step in if someone gets too forward with her, though she can usually handle it herself.', 'The Robo-Gladiators who treat her as a little sister, and the mercenary family of the IMCN camps that raised her (from the text; the block prints no allies line).', NULL, 'The youngest of the Robodome''s regular fighters, a prodigy raised in the IMCN''s mercenary camps who could run power armor and war machines by age twelve. She meant to become a mercenary like her parents until a weekend trip to the Robodome at sixteen; she borrowed a Samson from her mercenary family, entered open competition, and was signed, with an agent, inside three weeks. Rivals who dismissed her for her age or sex lost badly. She aims to win the Heavyweight title before thirty, and to become its first female champion if she beats Sarah Seymour to it. Young and fit, fair-skinned, with short dark hair and striking green eyes that are part of her public image.', 'Rifts World Book 34: Northern Gun Two p.24-25'),
('ng-ernest-gomez', 'Ernest "the Brute" Gomez', 'Ernest Gomez', 'Robodome Robo-Gladiator, two-time Middleweight Champion', 'rifts', 'Human', '9th level Coalition Elite RPA Pilot (as printed)', 9, 'Anarchist', '46', '6 feet, 3 inches (1.91 m)', '214 lbs (96 kg)', '{"IQ":12,"ME":9,"MA":21,"PS":14,"PP":22,"PE":13,"PB":12,"Spd":11}', 48, 19, NULL, NULL, NULL, NULL, NULL, '{"attacks":6}', 'Hand to hand: martial arts, six attacks per melee when outside his robot. The block prints no combat bonuses, saving throws or Horror Factor, and none are derived here.', '[{"name":"Dance","pct":75},{"name":"Language: American","pct":96},{"name":"Mathematics: Basic","pct":95},{"name":"Military Etiquette","pct":90},{"name":"Radio: Basic","pct":95},{"name":"Automobile","pct":93},{"name":"Hover Craft (ground)","pct":98},{"name":"Robots & Power Armor","pct":92},{"name":"Sensory Equipment","pct":85},{"name":"Weapon Systems","pct":95},{"name":"Lore: Magic","pct":45}]', 'Skills of note only; the block prints no full list. Piloting and math skills carry their catalog names (printed as Pilot: Automobile, Pilot: Hovercraft, Pilot: Robots & Power Armor and Math: Basic); Language: American has no catalog row and keeps its printed name. Lore: Magic is printed under Magic Knowledge, not the skill list. Without percentages: Robot Combat: Basic, Robot Combat Elite: NG Bruiser, Robot Combat Elite: UAR-1 Enforcer, Running, W.P. Energy Pistol, W.P. Energy Rifle, W.P. Heavy M.D. Weapons and Hand to Hand: Martial Arts.', NULL, 'None, but he knows Lore: Magic at 45%.', 'None.', NULL, 'Bionic left arm, replacing one lost in a gladiatorial bout, with a forearm laser (2D6 M.D.), knuckle spikes (1D4 M.D.), an E-Clip arm port and a fingerjack. Also a basic radio ear, a clock calendar and a gyro-compass.', 'Favors the NG-59 Ion Pistol (catalog row: NG-59 Ion Pistol and Grenade Launcher). Body armor: Urban Warrior - Padded Environmental Body Armor. Machines: his UAR-1 Enforcer Robot, stolen from the Coalition and cosmetically rebuilt to hide its origin, and the Bruiser Combat Robot (printed NG-V32 Bruiser). Vehicle: an unarmed Bandito Arms knock-off of the CS Skull Patrol Car.', NULL, 'Easygoing and fun-loving, he throws himself into the gladiator''s celebrity life and turns up at every party he can, as much because everyone likes him as because he enjoys them. Cheerful, warm toward people and content to let others live as they please, he has felt no real pressure since leaving the Coalition Army and counts himself the luckiest man in North America.', 'Many friends and political connections in the Robodome, and his loyal pit crew; league officials and NG brass might prefer to bury his secret rather than expose it (from the text; the block prints no allies line).', 'The Coalition States, which would try him as a deserter and thief (from the text; the block prints no enemies line).', 'A Coalition RPA pilot from Lone Star who went AWOL in 95 P.A., long before the Campaign of Unity, taking a brand new UAR-1 Enforcer with him. He spent years as a mercenary across the continent, working for clients as varied as Kingsdale, Whykin, El Dorado and the Pecos Empire, with the robot''s Death''s Head swapped for a plainer faceplate. A former Robodome fighter he met on an Arkansas job sold him on the arena, so he quit and headed for Ishpeming, where a customizing shop restyled the Enforcer so thoroughly that it now competes as a custom design. He has held the Middleweight title twice. Anyone who uncovers the robot''s origin has leverage over him: favors, blackmail, or getting him thrown out. Middle-aged and still carrying himself like a proud CS soldier, with a trimmed beard and mustache and hair grown out but kept neat. Also called Big Ern.', 'Rifts World Book 34: Northern Gun Two p.25-26');

INSERT INTO stat_attacks (owner_kind, owner_slug, name, damage, is_mega_damage, range, note, sort) VALUES
('notable_npc', 'ng-gerhardt-fulcon', 'TX-5 Triax Pump Pistol', '4D6 M.D.', 1, '800 feet (244 m)', 'Sidearm; the block names only a Triax pump pistol. Damage and range from the TX-5 catalog row (Triax and the NGR p.143).', 0),
('notable_npc', 'ng-brandon-church', 'Wilk''s 320 Laser Pistol', '1D6 M.D.', 1, '1000 feet (305 m)', 'Weapon of note; damage and range from its catalog row (Rifts Ultimate Edition p.268), the block prints none.', 0),
('notable_npc', 'ng-shelaine-truman', 'NG-33 Northern Gun Laser Pistol', '1D6 M.D.', 1, '800 feet (244 m)', 'Favorite weapon; damage and range from its catalog row (Rifts Ultimate Edition p.269), the block prints none.', 0),
('notable_npc', 'ng-shelaine-truman', 'L-20 Pulse Rifle', '2D6 M.D. single shot, or 6D6 M.D. triple pulse burst', 1, '1600 feet (488 m)', 'Favorite weapon; damage and range from its catalog row (Rifts Ultimate Edition p.270), the block prints none.', 1),
('notable_npc', 'ng-ernest-gomez', 'NG-59 Ion Pistol', '2D6 M.D.', 1, '400 feet (122 m)', 'Weapon of note; the ion damage and range from the NG-59 Ion Pistol and Grenade Launcher catalog row (Northern Gun One p.199), the block prints none. Its grenade launcher does 2D6 M.D. to a six-foot blast area at 500 feet (152 m).', 0),
('notable_npc', 'ng-ernest-gomez', 'Bionic Forearm Laser', '2D6 M.D.', 1, NULL, 'In the bionic left arm; the block prints no range.', 1),
('notable_npc', 'ng-ernest-gomez', 'Bionic Knuckle Spikes', '1D4 M.D.', 1, 'Melee', 'In the bionic left arm.', 2);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 4 notable NPCs are in' AS assertion, count(*) AS got, 4 AS want
  FROM notable_npcs WHERE slug IN ('ng-gerhardt-fulcon', 'ng-brandon-church', 'ng-shelaine-truman', 'ng-ernest-gomez');
SELECT 'and the notables 7' AS assertion, count(*) AS got, 7 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('ng-gerhardt-fulcon', 'ng-brandon-church', 'ng-shelaine-truman', 'ng-ernest-gomez');

